/**
 * Per-sheet story content — generated by combining the sheet's archetype
 * (Plan / Schedule / Detail / etc.) with the chapter's discipline.
 *
 * When the rookie clicks a sheet tab in the right pane, the left pane
 * rewrites itself to show this sheet-specific story instead of the
 * chapter-level overview. Three render fields per sheet:
 *
 *   - whatThisSheetShows  → one-paragraph summary of the sheet's purpose
 *   - whatsOnIt           → 3-4 bullets describing typical sheet contents
 *   - whenToUseIt         → one sentence explaining the field-work phase
 *   - watchOutFor         → 2 sheet-specific rookie-trap warnings
 *
 * Until Drew emits per-sheet narrative (post Wave 20.16 + REASON v2), we
 * derive content via per-archetype templates interpolated with the
 * chapter's discipline noun set. Pure functions — no state, no I/O.
 */

import type { SheetArchetype } from './archetype';

export interface PerSheetStory {
  whatThisSheetShows: string;
  whatsOnIt: string[];
  whenToUseIt: string;
  watchOutFor: string[];
  /** 2026-05-25 — Per-sheet buy-list. Empty array for archetypes that
   *  don't drive procurement (cover, index, legend, notes-only). Always
   *  present so the SheetView can render the zone with empty-state copy. */
  whatToBuy: string[];
  /** 2026-05-25 — Per-sheet field-work tasks (the contractor's
   *  actionable to-do list). Sequential where order matters (numbered
   *  in render). Always present; empty array for read-only sheets
   *  (cover/index/legend) where the render layer shows empty-state copy. */
  whatYouHaveToDo: string[];
}

/**
 * Discipline-noun set used to interpolate per-archetype templates. Each
 * discipline has a "domain", "fixtures", and "actor" — e.g. for plumbing:
 *   domain = "plumbing"
 *   fixtures = "fixtures, valves, and pipe runs"
 *   actor = "plumber"
 */
interface DisciplineNouns {
  domain: string;
  fixtures: string;
  actor: string;
}

const NOUNS: Record<string, DisciplineNouns> = {
  general: {
    domain: 'project-wide',
    fixtures: 'codes, rules, and references',
    actor: 'contractor',
  },
  demolition: {
    domain: 'demolition',
    fixtures: 'existing items to remove',
    actor: 'demo crew',
  },
  architectural: {
    domain: 'architectural',
    fixtures: 'partitions, doors, ceilings, and finishes',
    actor: 'framing + finish crew',
  },
  structural: {
    domain: 'structural',
    fixtures: 'beams, columns, slabs, and connections',
    actor: 'structural contractor',
  },
  plumbing: {
    domain: 'plumbing',
    fixtures: 'fixtures, valves, and pipe runs',
    actor: 'plumber',
  },
  mechanical: {
    domain: 'mechanical (HVAC)',
    fixtures: 'equipment, ductwork, and louvers',
    actor: 'mechanical contractor',
  },
  electrical: {
    domain: 'electrical',
    fixtures: 'devices, fixtures, panels, and circuits',
    actor: 'electrician',
  },
  fire: {
    domain: 'fire-protection',
    fixtures: 'sprinkler heads, drops, and alarm devices',
    actor: 'fire-protection contractor',
  },
  civil: {
    domain: 'civil / site',
    fixtures: 'grading, paving, and utility tie-ins',
    actor: 'site crew',
  },
};

function nounsFor(chapterKey: string): DisciplineNouns {
  return NOUNS[chapterKey] ?? NOUNS.general;
}

/**
 * Build the per-sheet story for a given (archetype, chapter key, sheet code,
 * sheet title) combination. Pure function — runs synchronously, no I/O.
 */
export function storyForSheet(
  archetype: SheetArchetype,
  chapterKey: string,
  sheetCode: string,
  sheetTitle: string,
): PerSheetStory {
  const n = nounsFor(chapterKey);
  const title = sheetTitle.trim();
  const titlePart = title.length > 0 ? ` (${title})` : '';

  switch (archetype) {
    case 'cover':
      return {
        whatThisSheetShows: `Project front-matter — title, address, owner, and applicable building codes. The first sheet anyone reads on the project${titlePart}.`,
        whatsOnIt: [
          'Project name, address, and date',
          'Applicable code editions (IBC, IMC, NFPA, plus local amendments)',
          'Project narrative / scope summary',
          'Sheet revision dates and addendum notes',
        ],
        whenToUseIt: 'Before any field work. Re-read after every addendum to catch scope changes.',
        watchOutFor: [
          'Addendum notes near the title block often change scope mid-project — easy to miss on a quick scan',
          'Local code amendments override the base code — confirm the AHJ accepted edition',
        ],
        whatToBuy: [],
        whatYouHaveToDo: [
          'Read the entire cover sheet before kickoff',
          'Note every addendum date — verify you have the latest set',
          'Confirm the applicable code editions match what your AHJ accepts',
          'Brief the crew on project name, address, and owner contact',
        ],
      };
    case 'index':
      return {
        whatThisSheetShows: `Sheet-by-sheet table of contents for the whole drawing set${titlePart}. Use it as your map.`,
        whatsOnIt: [
          'Sheet number + sheet title for every page',
          'Revision marks showing which sheets changed in the latest addendum',
          'Issue dates per sheet',
        ],
        whenToUseIt: 'When you need to find a specific sheet quickly. Especially useful before pricing.',
        watchOutFor: [
          'Missing sheet numbers in the index — they may have been pulled in a revision; chase before bidding',
          'Bid the index, not just the sheets you remember — easy to forget a small schedule sheet',
        ],
        whatToBuy: [],
        whatYouHaveToDo: [
          'Cross-check the index against the sheets in your set — flag any missing',
          'Use this as your bid checklist — price every sheet listed, not just the ones you remember',
          'Mark sheets revised in the latest addendum so you re-read those first',
        ],
      };
    case 'notes':
      return {
        whatThisSheetShows: `General ${n.domain} notes — the rules every ${n.actor} on this job has to follow${titlePart}.`,
        whatsOnIt: [
          `Standard ${n.domain} abbreviations + symbol legend`,
          `Project-specific ${n.domain} notes and any deviations from typical`,
          `Applicable code references and manufacturer specs`,
          'Materials specs and installation standards',
        ],
        whenToUseIt: `Before starting any ${n.domain} work. Refer back any time a callout is ambiguous on a plan sheet.`,
        watchOutFor: [
          'Hex notes referenced from plan sheets often live ONLY on the notes sheet — keep this one open while reading plans',
          `Project-specific overrides on this sheet beat the typical standard — read every line, don't skim`,
        ],
        // Notes sheets don't drive procurement on their own — they list
        // the SPECS the items must meet. Direct the rookie to the schedule.
        whatToBuy: [
          `Approved-manufacturer ${n.domain} materials per the spec list on this sheet`,
          'Cross-reference the schedule sheet in this chapter — that\'s where the line-item buy list lives',
        ],
        whatYouHaveToDo: [
          `Read every ${n.domain} note before pricing or starting work`,
          'Keep this sheet open next to the plan sheets so you can chase hex-note references quickly',
          'Brief every sub on the project-specific overrides — they beat the typical spec',
          'Flag any note that contradicts the schedule and resolve with the architect before bid',
        ],
      };
    case 'schedule':
      return {
        whatThisSheetShows: `The ${n.domain} parts catalog${titlePart}. Every ${n.fixtures.split(',')[0]} you'll buy, with exact spec.`,
        whatsOnIt: [
          'Item tag + manufacturer + model number',
          'Quantities, sizes, ratings, mounting heights',
          'Installation references back to plan sheets',
          'Owner-furnished vs. contractor-furnished callouts',
        ],
        whenToUseIt: 'Procurement. Take this to the supply house — every line is something you order or install.',
        watchOutFor: [
          'O.F.C.I. items (Owner Furnished, Contractor Installed) — don\'t buy these by mistake',
          'Long-lead items (specialty equipment) — flag for early order or you\'ll delay the schedule',
        ],
        // Schedules ARE the buy list — buyToBuy mirrors the schedule's
        // common categories so the rookie knows what columns to pull.
        whatToBuy: [
          `Every ${n.fixtures.split(',')[0]} on this schedule — by manufacturer + model number listed`,
          'Specified accessories: trims, escutcheons, connectors, mounting hardware',
          'Substitutes only with architect approval — get it in writing before ordering',
          'Long-lead items first — flag anything with a lead time > 4 weeks for early-order',
        ],
        whatYouHaveToDo: [
          'Pull every line item by tag, manufacturer, and model into your buy-list',
          'Verify quantities against the corresponding plan sheet (callout per tag)',
          'Flag any owner-furnished items so you don\'t double-order',
          'Submit substitution requests for unavailable items BEFORE ordering',
          'Track long-lead items in a separate sheet so you can pull them forward in the schedule',
        ],
      };
    case 'plan':
      return {
        whatThisSheetShows: `${n.domain.charAt(0).toUpperCase() + n.domain.slice(1)} layout in plan view${titlePart}. Where every ${n.fixtures.split(',')[0]} lives on the floor.`,
        whatsOnIt: [
          `Location of all ${n.fixtures}`,
          'Dimensions to gridlines and adjacent partitions',
          'Hex notes referencing the notes sheet',
          'Callouts to enlarged plans, details, and sections',
        ],
        whenToUseIt: `Rough-in stage. The ${n.actor} marks centerlines on the slab or in framing per this layout BEFORE anything gets closed up.`,
        watchOutFor: [
          `Dimensions on plan sheets are often to centerline of fixture — confirm before laying out`,
          'Callouts to other sheets are not optional — chase every "see X-XXX" reference before committing',
        ],
        // Per-discipline rough-in materials. The fixtures noun set already
        // names the major items — expand with the supporting hardware.
        whatToBuy: roughInBuyListFor(n),
        whatYouHaveToDo: roughInTaskListFor(n),
      };
    case 'rcp':
      return {
        whatThisSheetShows: `Reflected ceiling plan${titlePart} — what the ceiling looks like as if you were lying on the floor looking up.`,
        whatsOnIt: [
          'Ceiling grid, tile layout, and heights above finish floor',
          'Light fixture locations + diffuser positions',
          'Soffits, bulkheads, and ceiling-height changes',
          'Sprinkler head positions (sometimes — confirm with FP sheet)',
        ],
        whenToUseIt: 'Coordination phase. The RCP is where MEP collisions get caught BEFORE drywall closes the ceiling.',
        watchOutFor: [
          'Ceiling heights here override the floor plan — don\'t frame partitions to the wrong elevation',
          'Light + diffuser positions must coordinate with the grid — easy to set one off by a tile',
        ],
        whatToBuy: [
          'Ceiling grid (main tees, cross tees, wall angles) sized for the bay layout',
          'Ceiling tiles per spec — confirm fire rating + acoustic NRC value before ordering',
          'Light fixture trims + lay-in housings matching the grid module',
          'Diffuser frames + flexible duct connections per HVAC schedule',
          'Wire hangers, anchors, and seismic clips per code',
        ],
        whatYouHaveToDo: [
          'Coordinate with MEP trades BEFORE drywall closes the ceiling — last chance to catch collisions',
          'Set ceiling grid to the heights shown (overrides floor plan elevations)',
          'Position light fixtures + diffusers per the tile module (don\'t freelance)',
          'Hang and tie grid per seismic spec before tile install',
          'Walk the ceiling with each MEP foreman to sign off on coordination',
        ],
      };
    case 'detail':
      return {
        whatThisSheetShows: `${n.domain.charAt(0).toUpperCase() + n.domain.slice(1)} detail sheet${titlePart} — close-up views of specific assemblies, transitions, and connections.`,
        whatsOnIt: [
          'Detail callouts referenced from plan sheets',
          'Section views showing how parts fit together',
          'Material thicknesses + fastener specs',
          'Sometimes manufacturer install diagrams',
        ],
        whenToUseIt: 'Install stage. When the plan sheet says "see detail X/A-XXX", come here.',
        watchOutFor: [
          'Details sometimes contradict the typical note on the notes sheet — the detail wins for that location',
          'Scale changes per detail (3" = 1\'-0", 1-1/2" = 1\'-0", etc.) — read the scale bar each time',
        ],
        whatToBuy: [
          'Specified fasteners (screw type, length, gauge) per detail callout',
          'Sealants, gaskets, and weatherstripping at every transition shown',
          'Backer rod + closure pieces at expansion joints',
          'Connection hardware (clips, brackets, angles) per the connection detail',
        ],
        whatYouHaveToDo: [
          'Read the detail at the scale shown — don\'t assume from a smaller-scale plan',
          'Follow the assembly sequence shown (substrate → membrane → fastener → finish)',
          'Verify connection hardware matches the detail before installing',
          'Apply sealants per the manufacturer cure time before closing the assembly',
        ],
      };
    case 'section':
      return {
        whatThisSheetShows: `Building or wall section${titlePart} — what the building looks like if you sliced it in half along a specific line.`,
        whatsOnIt: [
          'Vertical relationships between floors, ceilings, roof',
          'Wall assembly thicknesses + material layers',
          'Structural elements (beams, columns) in profile',
          'Window and door head/sill heights',
        ],
        whenToUseIt: 'Framing + finishes. Confirms wall heights, soffit depths, and structural clearances.',
        watchOutFor: [
          'Section cut location matters — confirm WHICH wall you\'re looking at before measuring',
          'Heights from finish floor vs. top of slab vary — read the dimension reference points',
        ],
        whatToBuy: [
          'Studs and track sized for the full wall height shown in the section',
          'Sheathing and finish layers per the wall-assembly callout',
          'Sound or fire batt insulation matching the section assembly',
          'Header materials at every opening shown',
        ],
        whatYouHaveToDo: [
          'Layout walls to the heights and thicknesses shown in this section',
          'Confirm structural clearances above ceiling before MEP rough-in',
          'Verify head and sill heights at every opening match the section',
          'Set header sizes per the section before framing openings',
        ],
      };
    case 'elevation':
      return {
        whatThisSheetShows: `${n.domain.charAt(0).toUpperCase() + n.domain.slice(1)} elevation${titlePart} — a vertical view of a wall or face of the building.`,
        whatsOnIt: [
          'Window + door positions and heights',
          'Wall finish materials',
          'Signage + branding callouts',
          'Trim, base, and crown elevations',
        ],
        whenToUseIt: 'Trim + finishing stage. Used by the finisher to confirm what each wall face should look like.',
        watchOutFor: [
          'Mirrored elevations: A vs B is not always obvious — confirm which face you\'re looking at',
          'Finish material schedules live on a separate sheet — cross-reference before painting',
        ],
        whatToBuy: [
          'Wall finish materials (paint, wallcovering, tile, panels) per the elevation tags',
          'Base, chair rail, and crown per linear footage shown',
          'Window and door trim — confirm profile and material against the elevation',
          'Signage and graphics callouts — coordinate with the signage vendor',
        ],
        whatYouHaveToDo: [
          'Verify the elevation orientation (mirrored vs straight) before measuring',
          'Confirm finish material against the finish schedule before ordering',
          'Mark trim, base, and crown elevations on the wall before installing',
          'Coordinate signage mounting and electrical with the vendor and EC',
        ],
      };
    case 'demo':
      return {
        whatThisSheetShows: `Demolition + existing-conditions${titlePart}. What\'s currently there, and what\'s coming out before new work starts.`,
        whatsOnIt: [
          'Existing partitions, fixtures, and equipment marked for removal',
          'Items to PROTECT during demo (existing finishes that stay)',
          'Patch + repair scope where demo touches surfaces that stay',
          'Hatch patterns or notes distinguishing remove vs. relocate vs. salvage',
        ],
        whenToUseIt: 'Day 1 — walk the site with this sheet and tag every item before swinging the hammer.',
        watchOutFor: [
          'Hidden utilities behind walls — confirm cutoffs with the building engineer BEFORE cutting',
          'Items marked "salvage" or "relocate" require special handling — don\'t throw them in the dumpster',
        ],
        whatToBuy: [
          'Dumpster + disposal service sized for the scope shown',
          'Plastic sheeting + zip walls for dust containment around protected areas',
          'PPE (respirators, eye protection, gloves) for the crew + asbestos test kit if pre-1980',
          'Floor protection (Ram Board, hardboard) for surfaces marked to stay',
          'Salvage crates / pallets for items marked to relocate or owner-return',
        ],
        whatYouHaveToDo: [
          'Walk the site with this sheet on Day 1 and tag every item to remove',
          'Set up dust containment + floor protection on every surface marked to stay',
          'Coordinate utility cutoffs with the building engineer BEFORE any cutting',
          'Demo in the order shown — finishes first, then partitions, then MEP',
          'Crate and label any salvage/relocate items before they leave the site',
        ],
      };
    case 'lifesafety':
      return {
        whatThisSheetShows: `Egress + life-safety plan${titlePart}. Shows how people get OUT of the building if something goes wrong.`,
        whatsOnIt: [
          'Exit door locations + exit signs',
          'Egress paths + travel distances to nearest exit',
          'Fire-rated wall assemblies + rated openings',
          'Occupant load calculations',
        ],
        whenToUseIt: 'Permit submission + partition layout. Exit widths drive minimum corridor dimensions.',
        watchOutFor: [
          'Rated walls can\'t be penetrated without sleeve + sealant — coordinate with MEP',
          'Door swing direction matters for egress — wrong-direction swings fail the inspection',
        ],
        whatToBuy: [
          'Listed exit signs + emergency lighting per the egress plan',
          'Fire-rated wall assemblies (sheetrock, framing, batt) per UL listings shown',
          'Rated door + frame assemblies with proper hardware (closer, panic bar, smoke seal)',
          'Firestop sleeves + intumescent sealant for any rated-wall penetration',
        ],
        whatYouHaveToDo: [
          'Build rated walls to the UL assembly listed — no substitutions',
          'Frame corridors to the minimum egress width shown (drives partition layout)',
          'Install exit signs and emergency lighting along the egress path',
          'Sleeve and firestop every penetration through a rated wall — inspectors check this',
          'Hang doors with the correct swing direction per the plan (egress fails wrong-direction swings)',
        ],
      };
    case 'riser':
      return {
        whatThisSheetShows: `${n.domain.charAt(0).toUpperCase() + n.domain.slice(1)} riser diagram${titlePart} — vertical schematic showing how the system stacks floor-to-floor.`,
        whatsOnIt: [
          'Pipe / conduit sizes at each floor and main',
          'Branch connections to fixtures or panels per floor',
          'Direction of flow (or current direction for electrical)',
          'Cleanouts, valves, breakers, or other access points',
        ],
        whenToUseIt: 'Coordination + rough-in. Use the riser to confirm vertical alignment before any wall closes.',
        watchOutFor: [
          'Riser doesn\'t show horizontal routing — pair with the plan sheet for actual location',
          'Pipe / conduit sizes change at each branch — read the entire riser, not just one floor',
        ],
        whatToBuy: riserBuyListFor(n),
        whatYouHaveToDo: riserTaskListFor(n),
      };
    case 'legend':
      return {
        whatThisSheetShows: `${n.domain.charAt(0).toUpperCase() + n.domain.slice(1)} symbol legend${titlePart}. The dictionary for everything you\'ll see on the plan sheets.`,
        whatsOnIt: [
          'Each unique symbol shown with its plain-English meaning',
          'Line type definitions (existing vs new, hidden vs visible)',
          'Hatch patterns and what they represent',
          'Sometimes abbreviation expansions',
        ],
        whenToUseIt: 'Keep open while reading plans. Refer back any time a symbol is unfamiliar.',
        watchOutFor: [
          'Different disciplines reuse the same circle/square geometry for different things — always check the discipline\'s own legend',
          'Custom symbols vary per architect — don\'t assume the symbol means what it meant on the last project',
        ],
        whatToBuy: [],
        whatYouHaveToDo: [
          'Keep this sheet open while reading any discipline plan',
          'Brief the crew on symbol meanings before pre-construction',
          'Bookmark unusual symbols and confirm them with the architect',
        ],
      };
    case 'sheet':
    default:
      return {
        whatThisSheetShows: `${n.domain.charAt(0).toUpperCase() + n.domain.slice(1)} sheet${titlePart}. Drew is still classifying this sheet's archetype.`,
        whatsOnIt: [
          'Refer to the sheet title block for the architect\'s description',
          'Cross-reference with the notes and schedule sheets in this chapter',
          'Use the sheet legend (if present) to decode symbols',
        ],
        whenToUseIt: 'Read in context with the rest of the chapter.',
        watchOutFor: [
          'Drew is still extracting per-sheet structure — content here is generic until classification completes',
        ],
        whatToBuy: [],
        whatYouHaveToDo: [
          'Read the sheet title block for the architect\'s description',
          'Cross-reference with the schedule and notes sheets in this chapter',
        ],
      };
  }
}

// ---------------------------------------------------------------------------
// Discipline-aware buy-list helpers
// ---------------------------------------------------------------------------

/**
 * Rough-in materials per discipline for plan-type sheets. The fixtures
 * noun set already names the major items; we expand here with supporting
 * hardware and rough-in materials a contractor would stage before closing
 * the wall or ceiling.
 */
function roughInBuyListFor(n: DisciplineNouns): string[] {
  switch (n.domain) {
    case 'plumbing':
      return [
        'Pipe (copper, PEX, or PVC) sized per the riser + plan',
        'Fittings, valves, and shutoffs at every branch + fixture stub-out',
        'Pipe hangers, clamps, and isolation pads',
        'Fixture rough-in kits matching the fixture schedule',
        'Test caps + temporary closures for pressure testing',
      ];
    case 'electrical':
      return [
        'Conduit (EMT or PVC) sized per the panel schedule + plan',
        'Wire (THHN/THWN copper) sized per circuit ampacity',
        'Junction boxes, device boxes, and weatherproof boxes outside',
        'Breakers, panel directories, and grounding/bonding hardware',
        'Wire connectors, clamps, and bushings',
      ];
    case 'mechanical (HVAC)':
      return [
        'Ductwork (sheet metal or flex) sized per the equipment schedule',
        'Diffusers, grilles, and registers per RCP positions',
        'Equipment supports, vibration isolators, and seismic anchors',
        'Insulation wrap + duct sealant',
        'Filters, dampers, and access doors per the spec',
      ];
    case 'fire-protection':
      return [
        'Sprinkler pipe + heads matching the listed coverage spec',
        'Pipe hangers + sway bracing per NFPA 13',
        'Inspector\'s test connection + main drain assembly',
        'Sleeves + escutcheons at every wall/ceiling penetration',
        'Alarm devices (horns, strobes, pull stations) per the FA panel schedule',
      ];
    case 'architectural':
      return [
        'Studs + track sized for the partition heights',
        'Drywall (sheetrock) per the partition fire/sound rating',
        'Acoustic + fire batt insulation per the partition type',
        'Door + frame assemblies matching the door schedule',
        'Hardware (hinges, closers, levers) per the hardware schedule',
      ];
    case 'demolition':
      return [
        'Dumpster service + disposal manifests for the demo scope',
        'Floor + finish protection (Ram Board, poly, signage)',
        'PPE for the crew + dust-suppression equipment',
      ];
    case 'structural':
      return [
        'Beams, columns, and connectors per the shop drawings',
        'Anchor bolts + base plates matching the foundation plan',
        'Welding rod / bolts per the connection spec',
        'Bearing pads + grout under base plates',
      ];
    case 'civil / site':
      return [
        'Pipe + fittings for utility tie-ins per the site plan',
        'Aggregate (base, fill) per the grading + paving sections',
        'Erosion control (silt fence, inlet protection) per local permit',
      ];
    default:
      return [
        `Materials sized to the ${n.fixtures} layout shown on this plan`,
        'Cross-reference the schedule sheet for exact model/spec numbers',
      ];
  }
}

/**
 * Discipline-aware field-work tasks for plan-type sheets. Each list is
 * sequential — the SheetView renders them as numbered steps so the
 * rookie can work through them top-to-bottom.
 */
function roughInTaskListFor(n: DisciplineNouns): string[] {
  switch (n.domain) {
    case 'plumbing':
      return [
        'Mark fixture centerlines on the slab or framing per the plan layout',
        'Set carriers and rough-in valves at the correct elevations',
        'Run pipe from main to each fixture stub-out',
        'Test the rough-in (pressure or fill) before closing the wall',
        'Schedule rough-in inspection before drywall',
      ];
    case 'electrical':
      return [
        'Mark device + fixture locations on framing per the plan',
        'Pull conduit from panel to each device box',
        'Set boxes at correct mounting heights per spec',
        'Pull and label wire to each box',
        'Verify terminations before energizing the circuit',
      ];
    case 'mechanical (HVAC)':
      return [
        'Lay out equipment locations + ductwork routing per the plan',
        'Set equipment supports and vibration isolators',
        'Hang ductwork at the elevations shown',
        'Install diffusers + grilles per RCP positions',
        'Pressure-test ductwork before insulating',
      ];
    case 'fire-protection':
      return [
        'Lay out sprinkler head positions per the plan',
        'Run pipe and install heads at the listed coverage spec',
        'Install sway bracing + hangers per NFPA 13',
        'Sleeve and firestop every wall/ceiling penetration',
        'Complete hydrostatic test before sign-off',
      ];
    case 'architectural':
      return [
        'Lay out partitions per the dimensioned plan',
        'Frame walls to the partition type shown (gauge, height, fire rating)',
        'Install batt insulation per the partition type',
        'Hang and finish drywall to the specified level',
        'Set doors and hardware per the door schedule',
      ];
    case 'demolition':
      return [
        'Tag every item marked for removal on Day 1',
        'Set up dust containment and floor protection',
        'Disconnect utilities at cutoffs (confirm with engineer)',
        'Demo in sequence: finishes → partitions → MEP',
      ];
    case 'structural':
      return [
        'Lay out columns and beams per the foundation plan',
        'Set anchor bolts + base plates to the spec',
        'Erect framing per the connection details',
        'Schedule structural inspection before any cover-up',
      ];
    case 'civil / site':
      return [
        'Stake out the site per the civil plan',
        'Install erosion control before any earthwork',
        'Cut and fill to the grading plan elevations',
        'Tie utilities to the lines shown on the plan',
      ];
    default:
      return [
        `Lay out work per the dimensions shown on this plan`,
        'Cross-reference the schedule sheet for exact specs',
        'Inspect installed work against the plan before closing up',
      ];
  }
}

/**
 * Vertical-system buy list per discipline for riser diagrams. Focuses on
 * the materials that vary with stack height + branching.
 */
function riserBuyListFor(n: DisciplineNouns): string[] {
  switch (n.domain) {
    case 'plumbing':
      return [
        'Vertical pipe (cast iron, copper, or PVC) at the sizes shown each floor',
        'Cleanouts at every floor + base of stack',
        'Pipe sleeves + firestop at every floor penetration',
        'Riser clamps + supports per the floor framing',
      ];
    case 'electrical':
      return [
        'Vertical conduit at the sizes shown each floor',
        'Pull boxes at every floor for wire pulls',
        'Firestop putty + pillows at every floor penetration',
        'Cable supports + bushings per code',
      ];
    case 'mechanical (HVAC)':
      return [
        'Vertical duct + insulation per the equipment schedule',
        'Fire dampers + access doors at every rated-wall penetration',
        'Duct supports + seismic bracing per floor',
      ];
    case 'fire-protection':
      return [
        'Vertical riser pipe (Schedule 40 or 10) per the head count',
        'Standpipe valves + hose connections at each floor (if standpipe)',
        'Inspector\'s test + main drain at the base',
        'Sway bracing + hangers per NFPA 13',
      ];
    default:
      return [
        `Vertical ${n.fixtures.split(',')[0]} sized per the riser callouts`,
        'Supports + firestop at every floor penetration',
      ];
  }
}

/**
 * Discipline-aware tasks for riser diagrams. Vertical-coordination focus.
 */
function riserTaskListFor(n: DisciplineNouns): string[] {
  switch (n.domain) {
    case 'plumbing':
      return [
        'Confirm vertical alignment of stacks across every floor',
        'Install cleanouts at every floor + base of stack',
        'Sleeve and firestop every floor penetration before closing',
        'Hang riser supports per floor framing',
      ];
    case 'electrical':
      return [
        'Pull vertical conduit at the sizes shown each floor',
        'Set pull boxes at every floor for wire pulls',
        'Firestop every penetration before closing the chase',
        'Verify circuit feeds reach the correct floor panel',
      ];
    case 'mechanical (HVAC)':
      return [
        'Hang vertical duct + insulation per the diagram',
        'Install fire dampers at every rated-wall penetration',
        'Verify duct supports + seismic bracing each floor',
      ];
    case 'fire-protection':
      return [
        'Run vertical riser pipe to the head count shown',
        'Install standpipe valves + hose connections at each floor (if applicable)',
        'Mount inspector\'s test + main drain at the base',
        'Sway-brace per NFPA 13',
      ];
    default:
      return [
        'Confirm vertical alignment before closing any wall or floor',
        'Firestop every penetration through floor assemblies',
      ];
  }
}
